select x.topic, x.band, x.difficulty, x.q, x.options, x.answer_idx, x.explanation, x.source, 'verified'
  from jsonb_to_recordset($j$[{"topic":"history","band":"c6-8","difficulty":2,"q":"মহেঞ্জোদারো ও হরপ্পা কোন সভ্যতার নিদর্শন?","options":["মেসোপটেমীয় সভ্যতা","সিন্ধু সভ্যতা","চীনা সভ্যতা","মিসরীয় সভ্যতা"],"answer_idx":1,"explanation":"সিন্ধু সভ্যতা।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":2,"q":"মৌর্য সম্রাট অশোক কোন যুদ্ধের পর বৌদ্ধধর্ম গ্রহণ করেন?","options":["পানিপথের যুদ্ধ","কলিঙ্গ যুদ্ধ","বক্সারের যুদ্ধ","পলাশীর যুদ্ধ"],"answer_idx":1,"explanation":"কলিঙ্গ যুদ্ধ।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":3,"q":"মোগল সম্রাট আকবর যে নতুন ধর্মমত প্রবর্তনের চেষ্টা করেন তার নাম কী?","options":["ব্রাহ্ম ধর্ম","দীন-ই-ইলাহী","শিখ ধর্ম","জৈন ধর্ম"],"answer_idx":1,"explanation":"দীন-ই-ইলাহী।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":1,"q":"\"ঢাকাই মসলিন\" কীসের জন্য বিখ্যাত ছিল?","options":["কাঠের আসবাব","চামড়ার জুতা","অত্যন্ত মিহি সুতি কাপড়","মোটা পশমি কাপড়"],"answer_idx":2,"explanation":"অত্যন্ত মিহি সুতি কাপড়।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":3,"q":"ইংরেজ ইস্ট ইন্ডিয়া কোম্পানি কত সালে প্রতিষ্ঠিত হয়?","options":["১৬০০","১৮৫৭","১৫২৬","১৭০০"],"answer_idx":0,"explanation":"১৬০০।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":3,"q":"পলাশীর যুদ্ধের সময় বাংলার রাজধানী কোথায় ছিল?","options":["কলকাতা","মুর্শিদাবাদ","ঢাকা","চট্টগ্রাম"],"answer_idx":1,"explanation":"মুর্শিদাবাদ।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":3,"q":"ইউনেস্কো \"জামদানি বুননশিল্প\"-কে মানবতার অধরা সাংস্কৃতিক ঐতিহ্যের তালিকায় কত সালে অন্তর্ভুক্ত করে?","options":["২০২০","২০১৩","২০১৬","২০১৭"],"answer_idx":1,"explanation